import java.util.Scanner;
class Main {
	public static void main(String[] args){
		final int answer=100;
		try(Scanner scan = new Scanner(System.in)){
			int end = Integer.parseInt(scan.next());
			int dig = Integer.parseInt(scan.next());
			int cost =countDiv(end,dig);
			System.out.println(cost);
		}
	}
	public static int countDiv(int end, int dig){
		int maxL=Math.max(end, dig);
		int minR=Math.min(end, dig);

		if(maxL%minR==0){
			return minR;
		}else{
			return countDiv(maxL%minR,minR);
		}
	}
}

