import java.util.*;

class Main {
    public static void main(String args[]) {
            Scanner s = new Scanner(System.in);
            System.out.println(isPrime(s.nextInt(), s.nextInt()));
            s.close();
    }
    public static int isPrime(int total, int str) {
        if (total < str) {
            return isPrime(str, total);
        }
        if (str == 0) {
            return total;
        }
        return isPrime(str, total % str);
    }
}

