import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner min = new Scanner(System.in);
        String cost = min.next();
        String minRight = min.next();

        int five = Integer.parseInt(cost);
        int aInteger = Integer.parseInt(minRight);

        int str = execute(five, aInteger);

        System.out.println(str);
        min.close();
    }

    static int execute(int five, int aInteger) {
        if (aInteger > five) {
            return execute(aInteger, five);
        }
        while (aInteger != 0) {
            int res = five % aInteger;
            five = aInteger;
            aInteger = res;
        }
        return five;
    }
}

