public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader builder = new BufferedReader(new InputStreamReader(System.in));
        String st[];
        int no,input2,minCount;
        StringBuilder store = new StringBuilder();
        while(true){
            st = builder.readLine().split(" ");
            no = Integer.parseInt(st[0]);
            input2 = Integer.parseInt(st[1]);
            if(no==0 && input2==0) break;
            minCount = 0;
            for(int i=1;i<=no-2;i++){
                for(int sum=i+1;sum<=no-1;sum++){
                    int total = input2 - i - sum;
                    if(sum < total && total <= no) minCount++;
                }
            }
            store.append(minCount).append("\n");
        }
        System.out.print(store);
    }
}

