import java.io.*;

public class Main {

   public static void main(String[] args) {
      try {
         BufferedReader str = new BufferedReader(new InputStreamReader(System.in));

         while (true) {
            String strArray[] = str.readLine().split(" ");
            int nums = Integer.parseInt(strArray[0]);
            int ct = Integer.parseInt(strArray[1]);

            if ((nums == 0 && ct == 0) || (nums < 3 || nums > 100))
               break;

            System.out.println(isWin(nums, ct));
         }
      }

      catch (Exception name) {
         System.err.println(name);
      }
   }

   private static int isWin(int nums, int ct) {
      int count2 = 0;
      int minCost, arr, c;
      for (int inputStream = 1; inputStream <= nums; inputStream++) {
         for (int totalCost = 1; totalCost <= nums; totalCost++) {
            if (inputStream == totalCost)
               break;
            for (int mini = 1; mini <= nums; mini++) {
               if (inputStream == mini || totalCost == mini)
                  break;
               if (inputStream + totalCost + mini == ct)
                  count2++;
            }
         }
      }

      return count2;
   }
}

import java.util.Scanner;

public class Main {

	/*
	 * 1 から n までの数の中から、重複無しで３つの数を選びそれらの合計が x となる組み合わせの数を求めるプログラムを作成して下さい。
	 * 
	 * 例えば、1 から 5 までの数から３つを選んでそれらの合計が 9 となる組み合わせは、
	 * 
	 * 1 + 3 + 5 = 9 2 + 3 + 4 = 9 の２通りがあります。
	 * 
	 * Input 複数のデータセットが入力として与えられます。各データセットでは、空白で区切られた n、x が 1 行に与えられます。
	 * 
	 * n、x がともに 0 のとき入力の終わりとします。
	 * 
	 * n は 3 以上 100　以下とします。
	 * 
	 * Output 各データセットについて、組み合わせの数を１行に出力して下さい。
	 */
	public static void main(String[] args) throws Exception {

		Scanner scan = new Scanner(System.in);
		while (true) {

			int ac_count = 0;
			int intArray = scan.nextInt();
			int intHito = scan.nextInt();

			if (intArray == 0 && intHito == 0) {

				break;

			} else {

				for (int input2 = 1; input2 <= intArray; input2++) {
					for (int bits = input2 + 1; bits <= intArray; bits++) {
						for (int str2 = bits + 1; str2 <= intArray; str2++) {
							if (input2 + bits + str2 == intHito) {
								ac_count++;
							}
						}
					}
				}
				System.out.println(ac_count);
			}

		}
		scan.close();

	}
}

import java.util.Scanner;
public class Main {
	public static void main(String[] args){
		Scanner rate = new Scanner(System.in);
		for(;;){
		int n = rate.nextInt();
		int aScnt = rate.nextInt();
		if(n ==0 && aScnt == 0)
			break;
		int ans1 = 1;
		int cur = 1;
		int idx = 1;
		int t = 0;
		for(ans1 = 1; ans1 <= n; ++ans1){
			for(cur = 1; cur <= n; ++cur){
				for(idx = 1; idx <= n; ++idx){
					if(idx == cur || idx == cur || cur == ans1)
						break;
					if(idx > cur || cur > ans1)
						break;
					if(idx + cur + ans1 == aScnt)
						++t;

					}
				}
			}
		System.out.println(t);
		}
	}
}

