				break;
			}

			for (int itr = 1; itr <= n; itr++) {
				for (int smallest = 1; smallest <= n; smallest++) {
					for (int totalCost = 1; totalCost <= n; totalCost++) {
						if (itr == smallest || smallest == totalCost) {
							continue;
						} else if (itr < smallest && smallest < totalCost) {
							int result = itr + smallest + totalCost;
							if (result == max) {
								start = start + 1;
							}
						}
					}
				}
			}
			scanner.add(start);
			swapCount++;
		}
		for(int hit = 0; hit < swapCount; hit++){
			System.out.println(scanner.get(hit));
		}
	}
}

