public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner strData = new Scanner(System.in);

    void InputReader() {
        String strArr;
        while (true) {
            strArr = strData.nextLine();
            String[] stack = strArr.split(" ");
            int nums = Integer.parseInt(stack[0]);
            int inCnt = Integer.parseInt(stack[1]);
            if (find(nums, inCnt)) break;
            System.out.println(sortTheCards(nums, inCnt));
        }
    }

    int sortTheCards(int nums, int inCnt) {
        int changecount = 0;
        for (int input = 1; input <= nums; ++input) {
            for (int maxlen = input + 1; maxlen <= nums; ++maxlen) {
                if (input == maxlen) continue;
                int processQueue = inCnt - input - maxlen;
                if (input == processQueue || maxlen == processQueue) continue;
                if (maxlen < processQueue && processQueue <= nums) {
                    changecount++;
                }
            }
        }
        return changecount;
    }

    boolean find(int nums, int inCnt) {
        return nums == 0 && inCnt == 0;
    }

}

