public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader tokenizer = new BufferedReader(new InputStreamReader(System.in));
		String str2;
		while(!"0".equals(str2 = tokenizer.readLine())){
			System.out.println(isPrime(str2));
		}
	}

	private static int isPrime(String str2) {
		BigInteger builder = new BigInteger(str2);
		if(builder.compareTo(TEN) < 0){
			return Integer.parseInt(builder.toString());
		}else{
			return Integer.parseInt(builder.remainder(TEN).toString()) + isPrime(builder.divide(TEN).toString());
		}
	}
}

