    public static int find(int value, int start) { 
        // Everything divides 0  
        if (value == 0) 
          return start; 
        if (start == 0) 
          return value; 

        // base case 
        if (value == start) 
            return value; 

        // a is greater 
        if (value > start) 
            return find(value-start, start); 
        return find(value, start-value); 
    }

    public static long select(long value, long start) {
        return ((value % start) + start ) % start;
    }

