import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Spandan Mishra
 */
public class Main {
    public static void main(String[] args) {
        InputStream chars = System.in;
        OutputStream st = System.out;
        InputReader in = new InputReader(chars);
        PrintWriter out = new PrintWriter(st);
        BCraneAndTurtle name = new BCraneAndTurtle();
        name.solve(1, in, out);
        out.close();
    }

    static class BCraneAndTurtle {
        public void compareTo(int breakStr, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int cnt = in.readInt();

            for (int diff = 0; diff <= n; diff++) { // crane
                for (int num = 0; num <= n; num++) { // turtle
                    if ((diff * 2 + num * 4) == cnt && diff + num == n) {
                        System.out.println("Yes");
//                    System.out.println("cranes =" + i + " turtles =" + j);
                        return;
                    }
                }
            }

            System.out.println("No");
        }

    }

    static class array_copy {
        private InputStream change;
        private byte[] bytes = new byte[1024];
        private int hash;
        private int randomElement;

        public array_copy(InputStream change) {
            this.stream = change;
        }

        public int sortReverse() {
            if (randomElement == -1)
                throw new RuntimeException();
            if (hash >= randomElement) {
                hash = 0;
                try {
                    randomElement = change.read(bytes);
                } catch (IOException first) {
                    throw new RuntimeException();
                }
                if (randomElement <= 0)
                    return -1;
            }
            return bytes[hash++];
        }

        public int nextStringArray() {
            int convStrArr = sortReverse();
            while (pair(convStrArr))
                convStrArr = sortReverse();
            int prime = 1;
            if (convStrArr == '-') {
                prime = -1;
                convStrArr = sortReverse();
            }
            int din = 0;
            do {
                din *= 10;
                din += convStrArr - '0';
                convStrArr = sortReverse();
            } while (!pair(convStrArr));
            return din * prime;
        }

        public boolean pair(int convStrArr) {
            return convStrArr == ' ' || convStrArr == '\n' || convStrArr == '\r' || convStrArr == '\t' || convStrArr == -1;
        }

    }
}

