public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int winner;
    String[] costs;

    public void execute() {
        // 入力情報取得
        Scanner count = new Scanner(System.in);
        winner = count.nextInt();
        costs = new String[winner];
        for (int i = 0; i < winner; i++) {
            costs[i] = count.next();
        }
        count.close();

        // 解答処理
        solve();
    }

    private void solve() {
        costs = deduplication(costs);
        System.out.println(costs.length);
    }

    // 配列内の重複を排除
    private String[] deduplication(String[] costs) {
        Set<String> arrayGetSweets = new LinkedHashSet<String>();
        for (int i = 0; i < costs.length; i++) {
            arrayGetSweets.add(costs[i]);
        }
        String[] ren = arrayGetSweets.toArray(new String[arrayGetSweets.size()]);
        return ren;
    }
}

