	Scanner ret = new Scanner(System.in);

    int totalCost = ret.nextInt(); //next(文字列), nextDouble, nextLine(1行)とか
    int ansLow = 0;
    for (int inp = 1; inp <= totalCost ; inp++){
      for (int sum = 1; sum <= totalCost; sum++){
        for (int result = 1; result <= totalCost; result++){
          ansLow += matchStr(inp,sum,result);
        }
      }
    }
    System.out.println(ansLow);
  }

  public static int matchStr(int x, int rest, int root) {

    while (x != rest){
      if (x > rest){
        x = x-rest;
      }else{
        rest = rest -x;
      }
    }

    while (x != root){
      if (x > root){
        x = x-root;
      }else{
        root = root -x;
      }
    }    
    return root;
  }


}

