class Main {
  public static void main(String args[]) {
    Scanner suum = new Scanner(System.in);
    int total = suum.nextInt();
    suum.close();
    int start = 0;
    int[] ret = {0,0,0};
    for (int isr = 1; isr <= total; isr++) {
      for (int totalCost = 1; totalCost <= total; totalCost++) {
        for (int j2 = 1; j2 <= total; j2++) {
          ret[0] = isr;ret[1] = totalCost;ret[2] = j2;
          Arrays.sort(ret);
          start += selectionSort(ret);
        }
      }
    }

    System.out.println(start);
  }

  public static int selectionSort(int[] ret) {
    if (ret[1]%ret[0] == 0 && ret[2]%ret[0] == 0) {
      return ret[0];
    } else {
      for (int isr = ret[0]/2; isr > 0; isr--) {
        if (ret[0]%isr != 0) continue;
        if (ret[1]%isr == 0 && ret[2]%isr == 0) {
          return isr;
        }
      }
      return 1;
    }
  }
}

