import java.util.*;

public class Main {

	static int nextInt[][];

	public static void nextLong(int minCount) {
		nextInt = new int[minCount + 1][minCount + 1];
		for (int m = 0; m < minCount + 1; ++m) {
			for (int str1 = 0; str1 < minCount + 1; ++str1) {
				nextInt[m][str1] = -1;
			}
		}
	}

	public static int nextInt(int mat1, int cnt) {
		if(nextInt[mat1][cnt] != -1)return nextInt[mat1][cnt];
		if (mat1 < cnt) {
			int costPlus = mat1;
			mat1 = cnt;
			cnt = costPlus;
		}
		if (cnt == 0)
			return nextInt[mat1][cnt] = mat1;
		int brokenStairs = mat1 % cnt;
		return nextInt[mat1][cnt] = nextInt(cnt, brokenStairs);
	}

	public static int nextInt(int mat1, int cnt, int point) {
		return nextInt(nextInt(mat1, cnt), point);
	}

	public static void main(String args[]) {
		Scanner smallest = new Scanner(System.in);
		int swapCount = smallest.nextInt();
		nextLong(swapCount);
		smallest.close();
		long initialA = 0;
		for(int m = 1; m <= swapCount; ++m){
			for(int str1 = 1; str1 <= swapCount; ++str1){
				for(int ren = 1; ren <= swapCount; ++ren){
					initialA += nextInt(m, str1, ren);
				}
			}
		}
		System.out.println(initialA);
	}
}

