		long ans = 0;

		if(minSteps%count == 0) {
			System.out.println(ans);
		}else {
			long innerQuot = minSteps - (count * three);
			long divide = count * (three + 1) - minSteps;
			if(innerQuot <= divide) {
				System.out.println(innerQuot);
			}else {
				System.out.println(divide);
			}
		}
	}
}

