        Scanner str2 = new Scanner(System.in);
        long num = str2.nextLong();
        long checkDigits = str2.nextLong();
        str2.close();

        if(checkDigits == 1 || num == checkDigits) System.out.println("0");

        else if(checkDigits == 2){
            if(num % checkDigits == 0) System.out.println("0");
            else System.out.println("1");
        }

        else{
            while(true){
                if(num * 2 <= checkDigits) break;
                else if(Math.abs(num - checkDigits) > num) break;
                else if(num >= (long)Math.pow(checkDigits,2)) num = num % checkDigits;
                else num = Math.abs(num - checkDigits);
            }
            System.out.println(num);
        }
    }
}

