	private static long exception(long colNum[]) {
		long count_ = isEndline(colNum[0], colNum[1]);
		for (int seitoCount = 1; seitoCount < colNum.length-1; seitoCount++) {
			count_ = isEndline(count_, colNum[seitoCount+1]);
		}
		return count_;
	}

	// 最小公倍数を求める
	private static long getIntArray(long arr, long seitoList) {
		return (arr * seitoList) / isEndline(arr, seitoList);
	}

