public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner s = new FastScanner();
        final int splitString = s.nextInt();
        final int m = s.nextInt();
        int postime[] = s.nextIntArray(m);
        int quantum = 0;
        for (int debugDataPath = 0; debugDataPath < m; debugDataPath++)
            quantum += postime[debugDataPath];
        if (quantum < splitString)
            System.out.println("No");
        else
            System.out.println("Yes");
    }

    // FastScanner start
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] solver = new byte[1024];
        private int stringBuilder = 0;
        private int buflen = 0;

        private boolean nextCharArray() {
            if (stringBuilder < buflen) {
                return true;
            } else {
                stringBuilder = 0;
                try {
                    buflen = in.read(solver);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readArrayLong() {
            if (nextCharArray())
                return solver[stringBuilder++];
            else
                return -1;
        }

        private static boolean isPrintableChar(int score) {
            return 33 <= score && score <= 126;
        }

        public boolean nextStringArray() {
            while (nextCharArray() && !isPrintableChar(solver[stringBuilder]))
                stringBuilder++;
            return nextCharArray();
        }

        public String nextLine() {
            if (!nextStringArray())
                throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int array = readArrayLong();
            while (isPrintableChar(array)) {
                sb.appendCodePoint(array);
                array = readArrayLong();
            }
            return sb.toString();
        }

        public long nextByte() {
            if (!nextStringArray())
                throw new NoSuchElementException();
            long newProcess = 0;
            boolean res = false;
            int array = readArrayLong();
            if (array == '-') {
                res = true;
                array = readArrayLong();
            }
            if (array < '0' || '9' < array) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= array && array <= '9') {
                    newProcess *= 10;
                    newProcess += array - '0';
                } else if (array == -1 || !isPrintableChar(array)) {
                    return res ? -newProcess : newProcess;
                } else {
                    throw new NumberFormatException();
                }
                array = readArrayLong();
            }
        }

        public int nextLongArray() {
            long tokenizer = nextByte();
            if (tokenizer < Integer.MIN_VALUE || tokenizer > Integer.MAX_VALUE)
                throw new NumberFormatException();
            return (int) tokenizer;
        }

        public double nextDouble() {
            return Double.parseDouble(nextLine());
        }

        public int[] nextLongs(int newProcess) {
            int str[] = new int[newProcess];
            for (int debugDataPath = 0; debugDataPath < newProcess; debugDataPath++) {
                str[debugDataPath] = nextLongArray();
            }
            return str;
        }
    }
    // FastScanner end
}

