        for (long ints = 0; ints < tokenizer; ints++) {
            delimiter += in.longNext();
        }
        input.println((j <= delimiter) ? "Yes": "No");

        input.close();
    }

    static class FastScanner {
        BufferedReader str;
        StringTokenizer list;

        public FastScanner() throws IOException {
            str = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextLine() throws IOException {
            while (list == null || !list.hasMoreTokens())
                list = new StringTokenizer(str.readLine().trim());
            return list.nextToken();
        }

        long nextChar() throws IOException {
            return Long.parseLong(nextLine());
        }

        int readArray() throws IOException {
            return Integer.parseInt(nextLine());
        }

        double readLongArray() throws IOException {
            return Double.parseDouble(nextLine());
        }

        char charNext() throws IOException {
            return nextLine().charAt(0);
        }

        public int[] nextInt(final int tokenizer) throws IOException {
            final int[] round = new int[tokenizer];
            for (int ints = 0; ints < tokenizer; ints++)
                round[ints] = readArray();
            return round;
        }

        public long[] nextDouble(final int tokenizer) throws IOException {
            final long[] round = new long[tokenizer];
            for (int ints = 0; ints < tokenizer; ints++)
                round[ints] = nextChar();
            return round;
        }

        String getLine() throws IOException {
            return str.readLine().trim();
        }
    }
}

