import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) {
		Scanner cin = new Scanner(System.in);
		int N = cin.nextInt();
		long num = cin.nextLong();
		int rowNum = cin.nextInt();
		int dist[] = new int[rowNum];

		TreeMap<Integer, Integer> stack = new TreeMap<Integer, Integer>();

		for (int str = 0; str < dist.length; str++) {
			dist[str] = cin.nextInt();

			if (stack.containsKey(dist[str])) {
				stack.put(dist[str], stack.get(dist[str])+1);
			} else {
				stack.put(dist[str], 1);
			}
		}

		if (num>rowNum) {
			for (int str = 0; str < N; str++) {
				System.out.println("Yes");
			}
			return;
		}

		long line2 = rowNum-num + 1;

		Map<Integer, Integer> nums = new HashMap<>();

		for(Map.Entry<Integer, Integer> brokenNum : stack.entrySet()) {
			if (brokenNum.getValue() >= line2) {
				nums.put(brokenNum.getKey(), 1);
			}
		}

		for (int str = 1; str < N + 1; str++) {
			if (nums.containsKey(str)) {
				System.out.println("Yes");
			} else {
				System.out.println("No");
			}
		}
	}
}

