public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter output = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, output);
        output.close();
    }

    static class TaskA
    {
        public void sol(int min_number, Scanner in, PrintWriter output)
        {
            int nextMinNumber = in.nextInt();
            int[] acd = new int[nextMinNumber + 1];
            int[] arr = new int[nextMinNumber + 1];
            int[] costXN = new int[nextMinNumber];

            //Dishes
            for (int seki = 1; seki <= nextMinNumber; seki++)
            {
                acd[seki] = in.nextInt();
            }
            //Satisfactions
            for (int seki = 1; seki <= nextMinNumber; seki++)
            {
                arr[seki] = in.nextInt();
            }
            //C
            for (int seki = 1; seki < nextMinNumber; seki++)
            {
                costXN[seki] = in.nextInt();
            }

            //Eating
            int strData = 0;

            strData += arr[acd[1]];
            int counter = acd[1];

            for (int seki = 2; seki <= nextMinNumber; seki++)
            {
                strData += arr[acd[seki]];
                if (counter + 1 == acd[seki])
                {
                    strData += costXN[acd[seki - 1]];
                }
                counter = acd[seki];
            }
            output.print(strData);
        }

    }
