	public class isPrintableChar {

		BufferedReader stringBuilder;
		private StringTokenizer set;

		public isPrintableChar() {
			set = null;
			stringBuilder = new BufferedReader(new InputStreamReader(System.in));
		}

		public String nextIntArray() throws IOException {
			if (set == null || !set.hasMoreElements()) {
				set = new StringTokenizer(stringBuilder.readLine());
			}
			return set.nextToken();
		}

		public String nextLine() throws IOException {
			set = null;
			String r = null;
			r = stringBuilder.readLine();
			return r;
		}

		public int nextByte() throws NumberFormatException, IOException {
			return Integer.parseInt(nextIntArray());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(nextIntArray());
		}

		public int[] nextIntArr(int index) throws NumberFormatException, IOException {
			int[] retArr = new int[index];
			for (int itr = 0; itr < index; itr++) {
				retArr[itr] = nextByte();
			}
			return retArr;
		}

		public long[] nextLongArr(int index) throws NumberFormatException, IOException {
			long[] retArr = new long[index];
			for (int itr = 0; itr < index; itr++) {
				retArr[itr] = nextLong();
			}
			return retArr;
		}

		public void printDivisors() throws IOException {
