public class Main {

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int swapArray = toString(s);
		int[] minCount = isEndline(s);
		int[] string_data = isEndline(s);
		int[] str7 = isEndline(s);

		int testNumber = -1;
		int res = 0;
		for (int curStart = 0; curStart < swapArray; curStart++) {
			int convStrArr = minCount[curStart];
			res += string_data[convStrArr - 1];
			if (convStrArr - testNumber == 1) {
				res += str7[convStrArr - 2];
			}
			testNumber = convStrArr;
		}
		System.out.println(res);
	}

	/**
	 * *汎用メソッド<br>
	 * 入力した配列に対する順列を取得
	 *
	 * @param numArray
	 * @return
	 */
	private static List<Integer[]> upperbound(int[] bufferdReader) {
		List<Integer[]> convStrList = new ArrayList<>();
		Integer[] count = new Integer[bufferdReader.length];
		boolean[] isGood = new boolean[bufferdReader.length];

		return cost(convStrList, bufferdReader, count, isGood, 0);
	}

	/**
	 * *汎用メソッド(内部)<br>
	 * 入力した配列に対する順列を作成
	 *
	 * @param list
	 * @param numArray
	 * @param ans
	 * @param used
	 * @param depth
	 * @return
	 */
	private static List<Integer[]> cost(List<Integer[]> list, int[] bufferdReader, Integer[] count, boolean[] isGood,
			int output_data) {

		// 全部使い切った時=>できた順列を返す
		if (output_data == bufferdReader.length) {
			list.add(count.clone());
			return list;
		}
		// 使い切っていない場合

		for (int curStart = 0; curStart < bufferdReader.length; curStart++) {
			if (isGood[curStart]) {
				continue;
			}
			count[output_data] = bufferdReader[curStart];
			isGood[curStart] = true;
			list = cost(list, bufferdReader, count, isGood, output_data + 1);

			isGood[curStart] = false;
		}

		return list;
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をlongで返却
	 *
	 * @return
	 */
	public static long power(Scanner s) {

		return Long.parseLong(s.next());
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をintで返却
	 *
	 * @return
	 */
	public static int toString(Scanner s) {

		return Integer.parseInt(s.next());
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をStringで返却
	 *
	 * @return
	 */
	public static String solve(Scanner s) {

		return s.next();
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をint配列で返却
	 *
	 * @return
	 */
	public static int[] isEndline(Scanner s) {
		String eraser = "";
		// 直前にnext()を実行していると改行コードだけ取ってしまうのでその対策
		while (eraser.equals("")) {
			eraser = s.nextLine();
		}

		String[] arr = eraser.split(" ");
		int[] minIndex = new int[arr.length];
		for (int curStart = 0; curStart < arr.length; curStart++) {
			minIndex[curStart] = Integer.parseInt(arr[curStart]);
		}
		return minIndex;
	}

}

