		int[] start = new int[minM];		// 食べた料理の順番
		int[] list = new int[minM];		// 各料理の満足度
		int[] startcount = new int[minM - 1];		// 連番のときに追加で得られる満足度
		int len = Integer.MIN_VALUE;		// 直前に食べた料理の番号
