		for(int ren = 0; ren < minM; ren++) {
			start[ren] = seitoCount.nextInt();
		}
		for(int ren = 0; ren < minM; ren++) {
			list[ren] = seitoCount.nextInt();
		}
		for(int ren = 0; ren < minM - 1; ren++) {
			startcount[ren] = seitoCount.nextInt();
		}

		for(int ren = 0; ren < minM; ren++) {
			numbers += list[start[ren]-1];
			if(start[ren] - 1 == len) {
				numbers += startcount[start[ren] - 2];
			}
			len = start[ren];
		}

		System.out.println(numbers);

	}
