/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AX tokenizer = new AX();
        tokenizer.solve(1, in, out);
        out.close();
    }

    static class AX {
        public void InputIterator(int stringBuilder, FastReader splitString, PrintWriter out) {
            int time = splitString.nextInt();
            int answer = splitString.nextInt();
            out.println(Math.max(time + answer, Math.max(time * answer, time - answer)));
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] builder = new byte[1024];
        private int bufPointer;
        private int writer;
        private FastReader.SpaceCharFilter remainder;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int isPrintableChar() {
            if (writer == -1) {
                throw new InputMismatchException();
            }
            if (bufPointer >= writer) {
                bufPointer = 0;
                try {
                    writer = stream.read(builder);
                } catch (IOException name) {
                    throw new InputMismatchException();
                }
                if (writer <= 0) {
                    return -1;
                }
            }
            return builder[bufPointer++];
        }

        public int nextStr() {
            int min = isPrintableChar();
            while (isSpaceChar(min)) {
                min = isPrintableChar();
            }
            int sgn = 1;
            if (min == '-') {
                sgn = -1;
                min = isPrintableChar();
            }
            int substring = 0;
            do {
                if (min < '0' || min > '9') {
                    throw new InputMismatchException();
                }
                substring *= 10;
                substring += min - '0';
                min = isPrintableChar();
            } while (!isSpaceChar(min));
            return substring * sgn;
        }

        public boolean isSpaceChar(int min) {
            if (remainder != null) {
                return remainder.isSpaceChar(min);
            }
            return isEndline(min);
        }

        public static boolean isEndline(int min) {
            return min == ' ' || min == '\n' || min == '\r' || min == '\t' || min == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int list);

        }

    }
}

