class FastScanner {
	private final InputStream in = System.in;
	private final byte[] solver = new byte[1024];
	private int stringBuilder = 0;
	private int buflen = 0;

	private boolean nextCharArray() {
		if (stringBuilder < buflen) {
			return true;
		} else {
			stringBuilder = 0;
			try {
				buflen = in.read(solver);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readArrayLong() {
		if (nextCharArray())
			return solver[stringBuilder++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int score) {
		return 33 <= score && score <= 126;
	}

	public boolean nextStringArray() {
		while (nextCharArray() && !isPrintableChar(solver[stringBuilder]))
			stringBuilder++;
		return nextCharArray();
	}

	public String nextLine() {
		if (!nextStringArray())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int time = readArrayLong();
		while (isPrintableChar(time)) {
			sb.appendCodePoint(time);
			time = readArrayLong();
		}
		return sb.toString();
	}

	public long nextByte() {
		if (!nextStringArray())
			throw new NoSuchElementException();
		long newProcess = 0;
		boolean bufferPointer = false;
		int time = readArrayLong();
		if (time == '-') {
			bufferPointer = true;
			time = readArrayLong();
		}
		if (time < '0' || '9' < time) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= time && time <= '9') {
				newProcess *= 10;
				newProcess += time - '0';
			} else if (time == -1 || !isPrintableChar(time)) {
				return bufferPointer ? -newProcess : newProcess;
			} else {
				throw new NumberFormatException();
			}
			time = readArrayLong();
		}
	}

	public int nextLongArray() {
		long tokenizer = nextByte();
		if (tokenizer < Integer.MIN_VALUE || tokenizer > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) tokenizer;
	}

	public double nextIntArray() {
		return Double.parseDouble(nextLine());
	}
}

