 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream time = System.in;
        OutputStream array = System.out;
        Scanner in = new Scanner(time);
        PrintWriter results = new PrintWriter(array);
        B stepNum = new B();
        stepNum.solve(1, in, results);
        results.close();
    }

    static class B {
        public void prod(int gateNum, Scanner in, PrintWriter results) {
            // 入力
            int n = Integer.parseInt(in.next());
            int min_abs = Integer.parseInt(in.next());
            int end[] = new int[n];
            for (int card = 0; card < n; card++) {
                end[card] = Integer.parseInt(in.next());
            }

            int statuses[] = new int[n + 1];
            statuses[0] = 0;
            for (int card = 1; card <= n; card++) {
                statuses[card] = statuses[card - 1] + end[card - 1];
            }
            int minj = 0;
            for (int card = 0; card <= n; card++) {
                if (statuses[card] <= min_abs) ++minj;
            }

            // 出力
            results.println(minj);

        }

    }
}

