import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	static Scanner tokenizer;
	static long[][] invfact;
    static int input=1;
	public static void main(String[] args) {
	    tokenizer = new Scanner(System.in);

	    int n=combMod();
	    int cant=combMod();
        boolean[] current=new boolean[n+1];
        int[] max=new int[cant];
        invfact=new long[2][n+1];
        invfact[0][1]=1;
        invfact[1][1]=1;
        current[0]=true;
        current[n]=true;

        for (int cache=0; cache<cant;cache++) {
            max[cache]=combMod();
            current[max[cache]]=true;
            current[max[cache]-1]=true;
            current[max[cache]+1]=true;
            if(cache!=0 && max[cache]-max[cache-1] == 1) {
            	System.out.println(0);
            	return;
            }
        }

        long c=0;
        List<Long> result = new ArrayList<Long>();
        for (int cache=0; cache<n+1;cache++) {
            if(c!=0 && current[cache]) {
            	result.add(c);
            	c=0;
            } else if(!current[cache]) {
            	c++;
            }
        }

        long minNum=1;
        for (int cache=0; cache<result.size();cache++) {
        	long time_sum=result.get(cache);
        	minNum = (minNum*Process(time_sum)) % 1000000007l;
        }

        System.out.println(minNum);
	}

	public static long Process(long t) {
		if(input>=t) {
			return (invfact[0][(int)t]+invfact[1][(int)t]) % 1000000007l;
		}

		for (int cache=input+1; cache<=t; cache++) {
			invfact[0][cache]=invfact[1][cache-1];
			invfact[1][cache]=(invfact[0][cache-1] +invfact[1][cache-1]) % 1000000007l;
		}
		input=(int)t;
		return (invfact[0][(int)t]+invfact[1][(int)t]) % 1000000007l;
	}

	// a^nをmodで割ったあまり
	public static long dist(long max, long n, long brokenNum) {
		long square=1;
		while(n>0) {
			if((n & 1) == 1) square=square*max%brokenNum;
			max=max*max%brokenNum;
			n=n>>1;
		}

		return square;
	}

	// 文字列として入力を取得
	public static String minCostRecursive() {
		return tokenizer.next();
	}

	// intとして入力を取得
	public static int combMod() {
		return Integer.parseInt(tokenizer.next());
	}

	// longとして入力を取得
	public static long preCalcFactorials() {
		return Long.parseLong(tokenizer.next());
	}

	// doubleとして入力を取得
	public static double gd() {
		return Double.parseDouble(tokenizer.next());
	}
}

