    public static void main(final String[] args) throws Exception {
        final Scanner sumA = new Scanner(System.in);
        long N;
        N = sumA.nextLong();
        long index;
        index = sumA.nextLong();
        Set<Long> value = new HashSet<>();
        for(int brokenNum = 0 ; brokenNum < index ; brokenNum++){
            value.add(sumA.nextLong());
        }

        final Solver writer = new Solver();
        System.out.println(writer.solve(N, value));
    }
}

class Solver {
    final Map<Long, Long> pRemain = new HashMap<>();

    public long arrayLong(long N, Set<Long> value) {
        return select(0, N, value);
    }

    private long select(long start, long end, Set<Long> value) {
        if (pRemain.containsKey(start)) {
            return pRemain.get(start) % Main.MOD;
        }

        if (value.contains(start) || start > end) {
            return 0;
        }
        if (start == end) {
            return 1;
        }

        final long cost = select(start + 1, end, value) % Main.MOD;
        pRemain.put(start + 1, cost);

        final long S2 = select(start + 2, end, value) % Main.MOD;
        pRemain.put(start + 2, S2);

        return (cost + S2) % Main.MOD;
    }


}

