class readD implements Closeable {
	private final InputStream in;
	private final byte[] curChar = new byte[1024];
	private int r = 0;
	private int bytesRead = 0;
	public readD(InputStream in) {
		this.in = in;
	}
	private boolean readLineByte() {
		if (r < bytesRead) {
			return true;
		}else{
			r = 0;
			try {
				bytesRead = in.read(curChar);
			} catch (IOException ret) {
				ret.printStackTrace();
			}
			if (bytesRead <= 0) {
				return false;
			}
		}
		return true;
	}
	private int InputIterator() { if (readLineByte()) return curChar[r++]; else return -1;}
	private static boolean readHead(int c) { return 33 <= c && c <= 126;}
	public boolean hasNext() { while(readLineByte() && !readHead(curChar[r])) r++; return readLineByte();}
	public String nextStrings() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = InputIterator();
		while(readHead(b)) {
			sb.appendCodePoint(b);
			b = InputIterator();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long joinString = 0;
		boolean chars = false;
		int b = InputIterator();
		if (b == '-') {
			chars = true;
			b = InputIterator();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				joinString *= 10;
				joinString += b - '0';
			}else if(b == -1 || !readHead(b)){
				return chars ? -joinString : joinString;
			}else{
				throw new NumberFormatException();
			}
			b = InputIterator();
		}
	}
	public int nextInt() {
		long ex = nextLong();
		if (ex < Integer.MIN_VALUE || ex > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) ex;
	}
	public double nextDouble() { return Double.parseDouble(nextStrings());}
	public void finalize() {
		try {
			in.close();
		} catch (IOException ret) {
		}
	}
}

