import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class readArray {
    private BufferedReader reader = null;
    private StringTokenizer stringBuilder = null;

    public readArray(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      stringBuilder = null;
    }

    public String nextByte() {
      if (stringBuilder == null || !stringBuilder.hasMoreTokens()) {
        try {
          stringBuilder = new StringTokenizer(reader.readLine());
        } catch (IOException name) {
          throw new RuntimeException(name);
        }
      }
      return stringBuilder.nextToken();
    }

    public String nextChar() {
      if (stringBuilder == null || !stringBuilder.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException name) {
          throw new RuntimeException(name);
        }
      }

      return stringBuilder.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(nextByte());
    }

    public int nextInt() {
      return Integer.parseInt(nextByte());
    }

    public double nextDouble() {
      return Double.parseDouble(nextByte());
    }

    public int[] nextIntArray(int scanner) {
      int[] allCards = new int[scanner];
      for (int itr = 0; itr < scanner; itr++)
        allCards[itr] = nextInt();
      return allCards;
    }

    public long[] nextLongArray(int scanner) {
      long[] allCards = new long[scanner];
      for (int itr = 0; itr < scanner; itr++)
        allCards[itr] = nextLong();
      return allCards;
    }
  }

