public class Main {
	public static int lcm(int result,int checkDigits) {
		while(true) {
			result%=checkDigits;
			if(result==0)return checkDigits;
			checkDigits%=result;
			if(checkDigits==0)return result;
		}
	}
	public static void main(String[] args) throws IOException{
		BufferedReader arr=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer taro=new StringTokenizer(arr.readLine());
		int result=Integer.parseInt(taro.nextToken()),checkDigits=Integer.parseInt(taro.nextToken()),counter=Integer.parseInt(taro.nextToken());
		int bits=lcm(result,checkDigits),st=bits;
		while(counter>1) {
			if(bits%--st==0)--counter;
		}
		System.out.println(st);
	}
}

