public class Main {
    public static void main(String[] args) {
        InputStream line = System.in;
        OutputStream minIndex = System.out;
        Scanner in = new Scanner(line);
        PrintWriter alphabet = new PrintWriter(minIndex);
        B swapArray = new B();
        swapArray.solve(1, in, alphabet);
        alphabet.close();
    }

    static class B {
        public void gl(int minCost, Scanner in, PrintWriter alphabet) {
            // 入力
            int intData = Integer.parseInt(in.next());
            int m = Integer.parseInt(in.next());
            int count = Integer.parseInt(in.next());
            List<Integer> statuses = new ArrayList<>();

            int value = 1;
            while (true) {
                if (value > intData && value > m) break;

                if (intData % value == 0 && m % value == 0) statuses.add(value);

                value++;
            }

            Collections.sort(statuses, Collections.reverseOrder());
            // 出力
            alphabet.println(statuses.get(count - 1));

        }

    }
}

