public class Main {
    public static int solve(int now,int min,int costs[]){
       int input[] = new int[now+1];
        Arrays.fill(input,-1);
        input[0] = 0;
        input[1] = 0;
        input[2] = Math.abs(costs[1]-costs[2]);
        for(int inv=3;inv<=now;inv++){
            int minAbs= inv-min;
            int minDiff = Integer.MAX_VALUE;
            if(minAbs<=0) {
                minAbs = 1;
            }
            for(;minAbs<inv;minAbs++){
                 minDiff = Math.min(minDiff,input[minAbs]+Math.abs(costs[inv]-costs[minAbs]));
                 //System.out.println(i+" "+j+" "+dp[j]+" "+val);

            }
            input[inv] = minDiff;
        }
        return input[now];
    }
