public class Main {
    static int[] min;
    static int buflen;
    static int mod;
    static Integer[] tt;
    public static void main(String[] args) {
        InputReader arrList = new InputReader(System.in);
        buflen = arrList.nextInt();
        mod = arrList.nextInt();
        min = new int[buflen];
        tt = new Integer[buflen];
        for(int diff=0;diff<buflen;diff++){
            min[diff] = arrList.nextInt();
        }
        System.out.println(isPrintableChar(0));
    }

    static int isPrintableChar(int max){
        if(max == buflen-1){
            return 0;
        }
        if(tt[max]!=null){
            return tt[max];
        }
        int len = Integer.MAX_VALUE;
        for(int diff=1;diff<=mod;diff++) {
            if (max + diff < buflen) {
                int input = Math.abs(min[max] - min[max + diff]) + isPrintableChar(max + diff);
                len = Math.min(len, input);
            }
        }
        tt[max] = len;
        return len;
    }
}

