      for(int i = 0; i < n; i++)
      {
          value[i] = student.nextInt();
      }

      //Logic Part
      int size[] = new int[n];
      size[0] = 0;
      size[1] = Math.abs(value[1] - value[0]);
      for(int i = 2; i < n; i++)
      {
          size[i] = size[i-1] + Math.abs(value[i] - value[i-1]);
          for(int j = 2; j <= m; j++)
          {
              if(j <= i && j < n)
              {
                  size[i] = Math.min(size[i], size[i-j] + Math.abs(value[i] - value[i-j]));
              }
          }
      }
      colSum.println(size[n-1]);
      colSum.close();
    }
