class FastReader extends BufferedReader {
    char[] lenbuf = new char[1024];
    int minIndex = 0;
    int stringBuilder = 0;

    FastReader() {
        super(new InputStreamReader(System.in));
    }

    char nextInts() {
        if (minIndex == stringBuilder) {
            try {
                stringBuilder = super.read(lenbuf, 0, lenbuf.length);
            } catch (IOException inputLine) {
                inputLine.printStackTrace();
            }
            minIndex = 0;
        }
        return lenbuf[minIndex++];
    }

    void compare() {
        minIndex--;
    }

    boolean printd() {
        boolean printd;
        while (true) {
            char c = nextInts();
            if (!sortReverse(c)) {
                if (!(printd = c == '-')) compare();
                return printd;
            }
        }
    }

    void skip() {
        while (sortReverse(nextInts()));
        compare();
    }

    char[] factorialUsingRecursion(int second) {
        char[] lenbuf = new char[second];
        readLineByte(lenbuf, 0, second);
        return lenbuf;
    }

    public int readLineByte(char[] lenbuf, int bufferPointer, int chars) {
        skip();
        int initialize;
        for (initialize = 0; initialize < lenbuf.length; initialize++) {
            char c = nextInts();
            if (sortReverse(c)) {
                break;
            }
            lenbuf[initialize] = c;
        }
        return initialize;
    }

    boolean sortReverse(char c) {
        return c == ' ' || c == '\n' || c == '\r';
    }

    int initialize() {
        boolean printd = printd();
        int neg = 0;
        while (true) {
            int result = nextInts() - '0';
            if (result < 0 || 9 < result) break;
            neg = 10 * neg + result;
        }
        return printd ? -neg : neg;
    }

    int[] ii(final int second) {
        int[] max = new int[second];
        for (int sum = 0; sum < max.length; sum++) max[sum] = initialize();
        return max;
    }

    long check() {
        boolean printd = printd();
        long neg = 0;
        while (true) {
            int result = nextInts() - '0';
            if (result < 0 || 9 < result) break;
            neg = 10 * neg + result;
        }
        return printd ? -neg : neg;
    }
}

