import java.util.Scanner;

public class Main {
    static Scanner cnt = new Scanner(System.in);
    static long num1 = cnt.nextLong();
    static long mat2 = cnt.nextLong();
    static long stepNum[] = new long[(int)num1];
    static long sum[] = new long[(int)num1];
    public static void main(String[] args) {
        //初期化
        for (int temp = 0; temp < num1; temp++) {
            stepNum[temp] = cnt.nextInt();
            sum[temp] = 2147483647;
        }
        sum[0] = 0;
        for (int temp = 0; temp < num1; temp++){
            for (int total = 1; total <= mat2; total++){
                if (temp + total < num1)
                    sum[temp + total] = jump(sum[temp + total], sum[temp] + Math.abs(stepNum[temp + total] - stepNum[temp]));
            }
        }
        System.out.println(sum[(int)num1 - 1]);
    }
    public static long jump(long min, long count){
        if (min > count){
            return count;
        } else {
            return min;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	static class InputReader {
		BufferedReader ar;
		StringTokenizer st;

		public InputReader() {
			ar = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(ar.readLine());
				} catch (IOException line) {
					line.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInts() {
			return Integer.parseInt(next());
		}

		long nextLongs() {
			return Long.parseLong(next());
		}

		double nextSArray() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String string = "";
			try {
				string = ar.readLine();
			} catch (IOException line) {
				line.printStackTrace();
			}
			return string;
		}
	}

	private static long m[];

	private static long readLongsSplitByDelimiter(int arr[], int start, int marks, int round) {

		if (start >= round - 1)
			return 0;

		if (m[start] != 0)
			return m[start];
		long ans2 = Long.MAX_VALUE;

		for (int numberOfPprocess = 1; numberOfPprocess <= marks; numberOfPprocess++) {

			if (start + numberOfPprocess < round) {
				ans2 = Math.min(ans2, Math.abs(arr[start] - arr[start + numberOfPprocess]) + readLongsSplitByDelimiter(arr, start + numberOfPprocess, marks, round));
			}
		}
		return m[start] = ans2;

	}

	private static long compareTo(int arr[],int marks,int round) {

		m[0] = 0;
		m[1] = Math.abs(arr[1] - arr[0]);

		for(int input=2; input<arr.length; input++) {
			m[input] = Integer.MAX_VALUE;
			for(int numberOfPprocess = input - 1;  numberOfPprocess >= 0 && numberOfPprocess >=input - marks;  numberOfPprocess--  ) {

				m[input] = Math.min(m[numberOfPprocess] + Math.abs(arr[input] - arr[numberOfPprocess]) ,m[input] );

			}
		}
		return m[round-1];

	}

	public static void main(String[] args) {

		FastReader scan = new FastReader();

		int needle = scan.nextInt();
		int marks = scan.nextInt();

		int arr[] = new int[needle];

		for (int input = 0; input < needle; input++) {
			arr[input] = scan.nextInt();
		}
		m = new long[needle];
		System.out.println(compareTo(arr, marks, needle));

	}

}

