public class Main {
    static PrintWriter ar;
    static CF_Reader in;

    public static void main(String[] args) throws IOException {
        ar = new PrintWriter(new OutputStreamWriter(System.out));
        in = new CF_Reader();

        int scanner = in.intNext(), min = in.intNext();
        int[] strArr = in.nextIntArray(scanner);

        int[] strings = new int[scanner];
        strings[0] = 0;
        strings[1] = Math.abs(strArr[1] - strArr[0]);

        for (int itr = 2; itr < scanner; itr++) {
            int list = Math.max(itr - min, 0);
            int res = Integer.MAX_VALUE;
            for (int ans = list; ans < itr; ans++) {
                res = Math.min(res, (strings[ans] + Math.abs(strArr[ans] - strArr[itr])));
            }
            strings[itr] = res;
        }
        ar.println(strings[scanner-1]);

        ar.close();
    }


    static class readLineByte {
