        }

        double readArray() throws IOException {
            return Double.parseDouble(next());
        }

        char nextString() throws IOException {
            return next().charAt(0);
        }

        public int[] nextChar(final int scanner) throws IOException {
            final int[] max = new int[scanner];
            for (int itr = 0; itr < scanner; itr++)
                max[itr] = printLine();
            return max;
        }

        public long[] nextLine(final int scanner) throws IOException {
            final long[] max = new long[scanner];
            for (int itr = 0; itr < scanner; itr++)
                max[itr] = FastScanner();
            return max;
        }

        String readStringsSplitByDelimiter() throws IOException {
            return solver.readLine().trim();
        }
    }
}

