        Scanner calc=new Scanner(System.in);
        int t=calc.nextInt();
        int m=calc.nextInt();
        int minpatharr[]=new int[t];
        for(int list=0;list<t;list++){
            minpatharr[list]=calc.nextInt();
        }
        int min=0;
        int name[]=new int[t];
        name[0]=0;
        name[1]=Math.abs(minpatharr[1]-minpatharr[0]);
        for(int list=2;list<minpatharr.length;list++){
            min=Integer.MAX_VALUE;
            for(int minj=1;minj<=m;minj++){
                if(list-minj>=0){
