public class Main {
    private static final class FastInput {
        private final BufferedReader ar = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer str;

        private int nextIntArray() throws Exception {
            return Integer.parseInt(nextDouble());
        }

        private long next() throws Exception {
            return Long.parseLong(nextDouble());
        }

        private String nextDouble() throws Exception {
            if (str == null || !str.hasMoreElements()) str = new StringTokenizer(ar.readLine(), " ");
            return str.nextToken();
        }

        private long[] readLineInt(int minus) throws Exception {
            long[] arr = new long[minus];
            for (int input = 0; input < arr.length; input++) arr[input] = next();
            return arr;
        }
    }

    public static void main(String[] args) throws Exception {
        FastInput in = new FastInput();
        int needle = in.nextInt();
        int marks = in.nextInt();
        long[] ans = in.lineToIntArr(needle);
        long[] m = new long[needle+1];
        for(int input = 0; input <= needle; ++input){
            m[input] = 1000000007;
        }
        m[0] = 0;
        for(int input = 0; input < needle; ++input){
            for(int numberOfPprocess = 1; numberOfPprocess <= marks; ++numberOfPprocess){
                if(input + numberOfPprocess < needle)
                    m[input+numberOfPprocess] = Math.min(m[input+numberOfPprocess], m[input] + Math.abs(ans[input] - ans[input+numberOfPprocess]));
            }
        }
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        bw.write(String.valueOf(m[needle - 1]));
        bw.flush();
    }
}

