        Scanner bit = new Scanner(System.in);
        int result = bit.nextInt();
        int m = bit.nextInt();
        int[] num = new int[result];
        int[] temp = new int[result];
        for(int time=0;time<result;++time){
            num[time]=bit.nextInt();
        }
        if(result==0 || result==1)
            System.out.println("0");
        else {
            temp[1]=Math.abs(num[1]-num[0]);
            for (int time = 2; time < result; ++time) {
                int card = Integer.MAX_VALUE;
                int ren = time-m;
                if(ren<0)ren=0;
                for(int sum=ren;sum<time;++sum){
                    int cnt = temp[sum]+Math.abs(num[time]-num[sum]);
                    card = Math.min(card,cnt);
                }
                temp[time]=card;
            }
        }
        System.out.println(temp[result-1]);

    }
}

