import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream curChar = System.in;
        OutputStream bufPointer = System.out;
        InputReader in = new InputReader(curChar);
        PrintWriter ints = new PrintWriter(bufPointer);
        Task numChars = new Task();
        numChars.solve(in, ints);
        ints.close();
    }

    static class Task {
    	int height, t;

        void OutputWriter(InputReader in, PrintWriter ints) {
        	height = in.nextInt();
        	t = in.nextInt();

        	for (int get = 0; get <= height; ++get) {
        		for (int costIndexs = 0; costIndexs <= height - get; ++costIndexs) {
        			int obj = height - (get + costIndexs);
        			if (10000*get + 5000*costIndexs + 1000*obj == t) {
        				ints.println(String.format("%d %d %d", get, costIndexs, obj));
        				return;
        			}
        		}
        	}

        	ints.println("-1 -1 -1");
        }
    }

    static class readLongArray {
        BufferedReader delimiter;
        StringTokenizer r;

        readLongArray(InputStream stream) {
            delimiter = new BufferedReader(new InputStreamReader(stream));
            r = null;
        }

        String nl() {
            while (r == null || !r.hasMoreTokens()) {
                try {
                    r = new StringTokenizer(delimiter.readLine());
                } catch (IOException ar) {
                    throw new RuntimeException(ar);
                }
            }
            return r.nextToken();
        }

        int FastReader() {
            return Integer.parseInt(nl());
        }

        int[] readIntArray(int size) {
            int[] strings = new int[size];
            for (int i = 0; i < size; i++) {
                strings[i] = FastReader();
            }
            return strings;
        }

        long nextLong() {
            return Long.parseLong(nl());
        }

        long[] readArray(int size) {
            long[] strings = new long[size];
            for (int i = 0; i < size; i++) {
                strings[i] = nextLong();
            }
            return strings;
        }
    }
}

