public class Main {
  public static void main(String[] args) {


    Scanner sigma = new Scanner(System.in);
    // get a integer

    int sum3 = sigma.nextInt();
//    System.out.println(" integer is " + N);
    List<Integer> result = new ArrayList<>();
    List<Integer> cost = new ArrayList<>();
    int numberD = sigma.nextInt();
    int time_count = -1, souwa2 = -1, sigmaList = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int countA = 0; countA <= sum3 ; countA++){
      // i is equal to x
      double current = run(countA, sum3,  numberD);
      double end_count_now = sum3 -countA - current;
      if(sort(current,end_count_now, sum3)){
        time_count = countA;
        souwa2 = (int)current;
        sigmaList = (int)end_count_now;
        break;
      }
    }
    System.out.println(time_count + " " + souwa2 + " " + sigmaList);

  };
  private static double run(int countA,int sum3, int numberD) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double y = ((double)numberD - 9000 * (double)countA  - 1000* (double)sum3 ) /4000;
    return y;
  }

  public static boolean lowerbound(double array3, double sum3) {
    if(array3 ==(int)array3 && array3 >= 0 && array3 <= sum3){
      return true;
    }else{
      return false;
    }
  }
  public static boolean sort(double y, double diff, int sum3) {
    boolean sList = false, coordinateList = false;
    if(lowerbound(y, sum3)){
      sList = true;
    };
    if(lowerbound(diff, sum3)){
      coordinateList = true;
    }
    return sList && coordinateList;
  }
}

